
// xeokit.min.js (version simplifiée pour test)
// Simule un SDK avec une classe Viewer globale

class Viewer {
    constructor(config) {
        this.canvasId = config.canvasId;
        console.log("✅ Viewer initialisé avec canvas:", this.canvasId);
        this.scene = {
        objects: {},
        getAABB: () => ({ xmin: 0, ymin: 0, zmin: 0, xmax: 1, ymax: 1, zmax: 1 }),
        pick: ({ canvasPos }) => {
            console.log("🖱️ Pick appelé sur position", canvasPos);
            // Retourne une entité simulée
            return {
                entity: {
                    id: "demoPart",
                    name: "Partie 1",
                    colorize: [0.5, 0.5, 0.5]
                }
            };
        }
    };

        this.camera = {
            eye: [0, 0, 10],
            look: [0, 0, 0],
            up: [0, 1, 0]
        };
        this.cameraFlight = {
            flyTo: function({ aabb }) {
                console.log("📸 Camera flying to AABB:", aabb);
            }
        };
        this.canvas = document.getElementById(config.canvasId) || { toDataURL: () => "data:image/png;base64,..." };
    }
}

class XKTLoaderPlugin {
    constructor(viewer) {
        this.viewer = viewer;
    }
    load({ src, success }) {
        console.log("📦 Loading model from:", src);
        setTimeout(() => {
            console.log("✅ Model loaded");
            if (success) success();
        }, 1000);
    }
}
window.SectionPlanesPlugin = class {
    constructor(viewer) {
        console.log("🪓 SectionPlanesPlugin simulé");
        this.viewer = viewer;
    }
    removeSectionPlanes() {}
    createSectionPlane(config) { console.log("✂️ Plan de coupe appliqué", config); }
};

window.MeasurementsPlugin = class {
    constructor(viewer) {
        console.log("📏 MeasurementsPlugin simulé");
        this.viewer = viewer;
        this.active = false;
    }
};

window.AnnotationPlugin = class {
    constructor(viewer) {
        console.log("📝 AnnotationPlugin simulé");
        this.viewer = viewer;
    }
};


window.Viewer = Viewer;
window.XKTLoaderPlugin = XKTLoaderPlugin;
